def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            if kwargs:
                key_args = (args, frozendict(kwargs))
            else:
                key_args = args
            try:
                return cache[key(key_args)]
            except KeyError:
                result = func(*key_args)
                cache.setdefault(key_args, result)
                return result
        return wrapper
    return decorator

