def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    if not file_name or not text_buffer or not encoding:
        raise ValueError("Invalid arguments")
    if not isinstance(file_name, str) or not isinstance(encoding, str):
        raise TypeError("Invalid type of arguments")
    try:
        if not overwrite and os.path.exists(file_name):
            raise FileExistsError(f"File {file_name} already exists")
        with open(file_name, "a", encoding=encoding) as f:
            f.write(text_buffer)
        return len(text_buffer)
    except Exception as e:
        return -1

