def _legacy_mergeOrderings(orderings):
    merged = []
    for ordering in orderings:
        idx = len(merged) - 1
        while idx >= 0 and merged[idx] not in ordering:
            idx -= 1
        if idx >= 0:
            merged[idx + 1:] = ordering[idx + 1:]
        else:
            merged += ordering
    return merged

