def namesAndDescriptions(self, all=False):
        """Return attribute names and descriptions defined by interface."""
        # pylint: disable=redefined-builtin

        # Get the class object for this instance
        cls = type(self)

        # Get the list of all attributes defined by the interface
        interface_attrs = cls.__dictionary__.values()

        # Filter the attribute list to include only those with a description
        attrs_with_descs = [attr for attr in interface_attrs if hasattr(attr, 'description')]

        # If all is True, return all attributes with descriptions
        if all:
            return attrs_with_descs

        # Get the list of exportable attributes
        exportable_attrs = [
            attr for attr in attrs_with_descs
            if getattr(attr, 'is_exportable', True)
        ]

        # If all exportable attributes have a description, return them
        if all(map(lambda attr: hasattr(attr, 'description'), exportable_attrs)):
            return exportable_attrs

        # Otherwise, return a tuple of just the names and descriptions
        return (
            (attr.name, getattr(attr, 'description', None))
            for attr in exportable_attrs
            if hasattr(attr, 'description')
        )

