def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # check if the validator is runnable
    if not self.runnable:
        return prefix + "Validator is not runnable."

    # check if the validator has been run
    if not self.result:
        return prefix + "Validator has not been run."

    # format the result
    result_str = prefix + "Validator result: "
    if self.result == "pass":
        result_str += "passed"
    elif self.result == "fail":
        result_str += "failed"
    else:
        result_str += "errored"

    # add the message
    if self.message:
        result_str += " with message: " + self.message

    return result_str

