def check_digests_present_and_used(manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    manifest_files = list(filter( lambda x: x.endswith('.md5'), manifest_files))
    digests_used = list(filter( lambda x: x.endswith('.md5'), digests_used))
    if len(manifest_files) != len(digests_used):
        raise ValueError('Number of digests in manifest does not match the number of digests used.')
    manifest_digests = set(manifest_files)
    used_digests = set(digests_used)
    if len(manifest_digests) != len(used_digests):
        raise ValueError('Duplicate digest in manifest or used.')
    if not used_digests.issubset(manifest_digests):
        raise ValueError('A digest in used is not present in manifest.')
    return True

