def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    prior.check_inventory_integrity()

    # Check that the prior inventory is an earlier version than the current inventory
    if not self.inventory_date < prior.inventory_date:
        raise InvalidInventoryException("The prior inventory is not an earlier version than the current inventory")

    # Check that all items in the prior inventory are present in the current inventory
    for item in prior.items.values():
        if item not in self.items.values():
            raise InvalidInventoryException(f"Item '{item.name}' is missing from the current inventory")

    # Check that all items in the current inventory were present in the prior inventory
    for item in self.items.values():
        if item not in prior.items.values():
            raise InvalidInventoryException(f"Item '{item.name}' is not present in the prior inventory")

    # Check that all items in the current inventory have the same quantity as in the prior inventory
    for item in self.items.values():
        if item.quantity != prior.items[item.name].quantity:
            raise InvalidInventoryException(f"Item '{item.name}' has a different quantity in the current inventory than in the prior inventory")

    return True

