def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check that fixity is a dictionary
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary, got {}".format(type(fixity)))

    # Check that there are no unsupported algorithms
    supported_algorithms = ['sha256', 'sha512']
    for algorithm in fixity.keys():
        if algorithm not in supported_algorithms:
            raise ValueError("Unsupported algorithm '{}' in fixity block".format(algorithm))

    # Check that all files listed in the fixity block are present in the manifest
    for file_path in fixity.values():
        if file_path not in manifest_files:
            raise ValueError("File '{}' in fixity block is not present in the manifest".format(file_path))

    # Check that there are no duplicate files in the fixity block
    if len(fixity) != len(set(fixity)):
        raise ValueError("Duplicate files in fixity block")

    # Check that each file has a unique set of algorithms
    algorithm_set = set()
    for algorithm, file_paths in fixity.items():
        for file_path in file_paths:
            algorithm_set.add((algorithm, file_path))
    if len(algorithm_set) != len(fixity):
        raise ValueError("Duplicate files with the same algorithm in fixity block")

