def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    normalized_kwargs = {}
    for attr, value in self.kwargs.items():
        if attr.endswith('days') or attr.endswith('hours') or attr.endswith('minutes') or attr.endswith('seconds') or attr.endswith('microseconds') or attr.endswith('weeks'):
            normalized_kwargs[attr] = int(value)
        elif attr.endswith('months') or attr.endswith('years'):
            normalized_kwargs[attr] = int(value)
        else:
            normalized_kwargs[attr] = value
    return relativedelta(**normalized_kwargs)

