    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise TypeError("commands must be a string or a list of strings")
        if verbose:
            print("Running command:", command)
        result = subprocess.run(command, args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        if result.returncode != 0:
            raise RuntimeError("Command returned non-zero exit status:", result.returncode)
        if hide_stderr:
            print(result.stdout.decode("utf-8"))
        else:
            print(result.stdout.decode("utf-8"), result.stderr.decode("utf-8"))

