def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate} does not provide {iface.__name__}")

    missing_methods = []
    for name, sig in iface.namesAndSignatures():
        if not hasattr(candidate, name):
            missing_methods.append(name)
            continue
        if not isinstance(getattr(candidate, name), types.MethodType):
            raise zope.interface.Invalid(f"Invalid signature for method {name}: "
                                        f"expected {sig.__name__}, "
                                        f"got {getattr(candidate, name).__name__}")

    missing_attrs = []
    for name, v in iface.namesAndDescriptions():
        if not hasattr(candidate, name):
            missing_attrs.append(name)
            continue
        if not isinstance(getattr(candidate, name), type(v)):
            raise zope.interface.Invalid(f"Invalid type for attribute {name}: "
                                        f"expected {type(v).__name__}, "
                                        f"got {type(getattr(candidate, name)).__name__}")

    if missing_methods or missing_attrs:
        raise zope.interface.Invalid(f"{candidate} is missing the following items: "
                                    f"{', '.join(missing_methods)}; "
                                    f"{', '.join(missing_attrs)}")

    if vtype is not None:
        try:
            validator = zope.interface.getValidator(iface, vtype)
        except KeyError:
            raise zope.interface.Invalid(f"No validator for type {vtype} in {iface}")

        try:
            validator(candidate)
        except zope.interface.Invalid as e:
            raise e

    return True

