def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. Check if this is a legacy payload.
    """
    if not isinstance(request, RequestType):
        raise ValueError("Expected a RequestType object, got {type(request)}")
    if request.data is None:
        return False

    public_ident = request.data.get("public_message", {}).get("ident", None)
    if public_ident is not None:
        return True

    private_ident = request.data.get("private_message", {}).get("ident", None)
    if private_ident is not None:
        return True

    if request.legacy_payload and request.limited_payload and request.data.get("payload") is not None:
        return True

