def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for key, value in args.items():
        minimum = getattr(self, f'_{key}_min', None)
        maximum = getattr(self, f'_{key}_max', None)
        if minimum is not None and value < minimum:
            raise ValueError(f'{key} must be greater than or equal to {minimum}.')
        if maximum is not None and value > maximum:
            raise ValueError(f'{key} must be less than or equal to {maximum}.')

